<script setup lang="ts">import {DialogRoot,DialogPortal,DialogOverlay,DialogContent,DialogTitle,DialogClose} from 'reka-ui';import {X} from 'lucide-vue-next';const ui=useUiStore(),quantity=ref(1),name=ref(''),note=ref('');const {openWhatsApp}=useWhatsApp();async function submit(){if(!ui.orderProduct)return;await openWhatsApp(ui.orderProduct,quantity.value,name.value,note.value);ui.orderProduct=null}</script>
<template><DialogRoot :open="!!ui.orderProduct" @update:open="v=>{if(!v)ui.orderProduct=null}"><DialogPortal><DialogOverlay class="overlay"/><DialogContent class="dialog" aria-describedby="order-description"><div class="head"><div><span class="eyebrow">PESAN VIA WHATSAPP</span><DialogTitle class="title">Tanyakan produk</DialogTitle></div><DialogClose class="close"><X/></DialogClose></div><p id="order-description" class="muted">Pesanan belum dibuat. Detail ini hanya menyusun pesan WhatsApp Anda.</p><div><label class="label">Produk</label><input class="field" :value="ui.orderProduct?.name" readonly></div><div><label class="label">Jumlah</label><input v-model.number="quantity" class="field" type="number" min="1"></div><div><label class="label">Nama <span class="muted">(opsional)</span></label><input v-model="name" class="field"></div><div><label class="label">Catatan <span class="muted">(opsional)</span></label><textarea v-model="note" class="field" rows="3" placeholder="Ukuran, warna, atau kebutuhan lainnya"/></div><button class="btn btn-gold" @click="submit">Lanjut ke WhatsApp</button></DialogContent></DialogPortal></DialogRoot></template>
<style scoped>.overlay{position:fixed;inset:0;background:#0008;z-index:80}.dialog{position:fixed;z-index:81;top:50%;left:50%;transform:translate(-50%,-50%);width:min(480px,calc(100% - 28px));background:white;border-radius:16px;padding:1.5rem;display:grid;gap:1rem;box-shadow:0 24px 80px #0004}.head{display:flex;justify-content:space-between}.title{font-size:1.5rem;font-weight:750}.close{border:0;background:none}.dialog>.btn{width:100%}</style>
